<?php require_once __DIR__.'/comman/auth.php'; $pageTitle="Media Library"; require __DIR__.'/comman/header.php'; require __DIR__.'/comman/sidebar.php'; ?><div class="content-wrapper"><section class="content-header"><div class="container-fluid"><div class="row mb-2"><div class="col-sm-8"><h1><?=h($pageTitle)?></h1></div></div><?php if($flash):?><div class="alert alert-<?=h($flash[0])?>"><?=h($flash[1])?></div><?php endif;?></div></section><section class="content"><div class="container-fluid"><?php $msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(isset($_FILES['media'])&&$_FILES['media']['error']===UPLOAD_ERR_OK){$f=$_FILES['media'];$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));$allowed=['jpg','jpeg','png','webp','gif','svg','mp4','webm'];if(!in_array($ext,$allowed,true))$msg='Unsupported file type.';elseif($f['size']>15*1024*1024)$msg='Maximum 15MB.';else{$dir=SITE_ROOT.'/assets/uploads';if(!is_dir($dir))mkdir($dir,0755,true);$safe=preg_replace('/[^a-zA-Z0-9._-]+/','-',basename($f['name']));move_uploaded_file($f['tmp_name'],$dir.'/'.$safe);$msg='Uploaded: /assets/uploads/'.$safe;}}}$files=[];$dir=SITE_ROOT.'/assets/uploads';if(is_dir($dir))foreach(scandir($dir) as $f)if($f!=='.'&&$f!=='..')$files[]=$f;?><div class="card"><div class="card-header"><h3 class="card-title">Upload Image / Video</h3></div><div class="card-body"><?php if($msg):?><div class="alert alert-info"><?=h($msg)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input class="form-control-file mb-3" type="file" name="media" required><button class="btn btn-pink">Upload</button></form></div></div><div class="card"><div class="card-header"><h3 class="card-title">Uploaded Media</h3></div><div class="card-body"><div class="row"><?php foreach($files as $f):?><div class="col-sm-3 mb-3"><div class="border rounded p-2"><?php if(preg_match('/\.(jpg|jpeg|png|webp|gif)$/i',$f)):?><img src="../assets/uploads/<?=h($f)?>" style="width:100%;height:120px;object-fit:cover;border-radius:8px"><?php else:?><div style="height:120px;display:flex;align-items:center;justify-content:center"><i class="fas fa-video fa-2x"></i></div><?php endif;?><small class="d-block mt-2"><?=h($f)?></small><button type="button" class="btn btn-sm btn-outline-secondary mt-1" onclick="navigator.clipboard.writeText(location.origin+'/assets/uploads/<?=h($f)?>')">Copy URL</button></div></div><?php endforeach;?></div></div></div></div></section></div><?php require __DIR__.'/comman/footer.php'; ?>